:root {
  --ink: #f4efe2;
  --ink-soft: #c9c3b4;
  --ink-dim: #8d8a7f;
  --gold: #e6c27c;
  --gold-bright: #f4d795;
  --gold-deep: #a97f3e;
  --moss: #8b9d5a;
  --forest: #293221;
  --panel: rgba(17, 21, 14, 0.72);
  --panel-solid: #151a12;
  --line: rgba(255, 249, 232, 0.13);
  --line-strong: rgba(255, 249, 232, 0.23);
  --shadow: 0 30px 80px rgba(0, 0, 0, 0.45);
  --display: "Trebuchet MS", "Avenir Next", "Segoe UI", sans-serif;
  --body: ui-sans-serif, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  --mono: "SFMono-Regular", ui-monospace, Menlo, Consolas, "Liberation Mono", monospace;
  --safe-bottom: env(safe-area-inset-bottom, 0px);
  --safe-top: env(safe-area-inset-top, 0px);
}

* {
  box-sizing: border-box;
}

html,
body {
  margin: 0;
  min-height: 100%;
  background: #0d110b;
  color: var(--ink);
  font-family: var(--body);
  -webkit-font-smoothing: antialiased;
  overscroll-behavior: none;
}

body {
  overflow: hidden;
  user-select: none;
}

button,
input,
select {
  font: inherit;
}

button {
  color: inherit;
}

#app {
  position: fixed;
  inset: 0;
  overflow: hidden;
  background:
    radial-gradient(circle at 70% 40%, #53633c 0%, transparent 45%),
    linear-gradient(180deg, #91adc4 0%, #d2b081 45%, #38432d 100%);
}

#scene {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  touch-action: none;
  outline: none;
}

.world-tint {
  position: absolute;
  inset: 0;
  pointer-events: none;
  background:
    linear-gradient(90deg, rgba(9, 13, 8, 0.87) 0%, rgba(9, 13, 8, 0.5) 30%, rgba(9, 13, 8, 0.05) 58%, rgba(9, 13, 8, 0.3) 100%),
    linear-gradient(180deg, rgba(10, 14, 9, 0.46) 0%, transparent 26%, transparent 68%, rgba(9, 12, 8, 0.66) 100%);
  transition: opacity 0.7s ease;
}

body.in-game .world-tint {
  opacity: 0;
}

.vignette {
  position: absolute;
  inset: 0;
  pointer-events: none;
  background: radial-gradient(ellipse at center, transparent 45%, rgba(4, 7, 3, 0.4) 100%);
  mix-blend-mode: multiply;
}

.grain {
  position: absolute;
  inset: -50%;
  pointer-events: none;
  opacity: 0.045;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.9' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.8'/%3E%3C/svg%3E");
  animation: grain-shift 0.7s steps(2) infinite;
}

@keyframes grain-shift {
  0% { transform: translate(0, 0); }
  25% { transform: translate(1.5%, -1%); }
  50% { transform: translate(-1%, 1.5%); }
  75% { transform: translate(1%, 0.5%); }
  100% { transform: translate(-1.5%, -0.5%); }
}

.screen {
  position: absolute;
  inset: 0;
  z-index: 10;
  transition: opacity 0.4s ease, visibility 0.4s ease;
}

.screen.is-hidden,
.is-hidden {
  opacity: 0 !important;
  visibility: hidden !important;
  pointer-events: none !important;
}

.menu-screen {
  display: flex;
  flex-direction: column;
  padding: clamp(20px, 2.6vw, 38px) clamp(22px, 5vw, 76px) clamp(18px, 2.6vw, 34px);
}

.menu-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  flex: none;
}

.brand {
  display: flex;
  align-items: center;
  gap: 10px;
  letter-spacing: 0.14em;
  font-size: 12px;
  font-weight: 800;
}

.brand-cube {
  width: 25px;
  height: 25px;
  filter: drop-shadow(0 2px 8px rgba(0, 0, 0, 0.35));
}

.brand-word {
  color: #f8f1df;
}

.brand-version {
  color: var(--ink-dim);
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: 0.08em;
  border: 1px solid var(--line);
  border-radius: 4px;
  padding: 2px 4px;
}

.server-chip {
  display: flex;
  align-items: center;
  gap: 9px;
  padding: 8px 13px;
  border: 1px solid var(--line);
  background: rgba(12, 16, 10, 0.36);
  border-radius: 999px;
  backdrop-filter: blur(10px);
  font-family: var(--mono);
  font-size: 10px;
  letter-spacing: 0.07em;
  color: var(--ink-soft);
}

.pulse-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: #9cc26b;
  box-shadow: 0 0 0 4px rgba(156, 194, 107, 0.12);
  animation: pulse 2.4s ease-in-out infinite;
}

@keyframes pulse {
  0%, 100% { box-shadow: 0 0 0 4px rgba(156, 194, 107, 0.1); }
  50% { box-shadow: 0 0 0 7px rgba(156, 194, 107, 0.02); }
}

.server-divider {
  width: 1px;
  height: 10px;
  background: var(--line-strong);
}

.server-time {
  color: var(--ink-dim);
}

.menu-body {
  flex: 1;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: clamp(30px, 5vw, 90px);
  min-height: 0;
  padding-top: clamp(20px, 4vh, 52px);
}

.hero {
  width: min(650px, 58vw);
  animation: hero-in 1s cubic-bezier(0.2, 0.7, 0.2, 1) both;
}

@keyframes hero-in {
  from { opacity: 0; transform: translateY(22px); }
  to { opacity: 1; transform: translateY(0); }
}

.eyebrow {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-bottom: 18px;
  font-family: var(--mono);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.28em;
  color: var(--gold);
}

.eyebrow span {
  display: block;
  width: 32px;
  height: 1px;
  background: linear-gradient(90deg, var(--gold), transparent);
}

.title {
  margin: 0;
  font-family: var(--display);
  font-size: clamp(66px, 8.4vw, 142px);
  line-height: 0.78;
  letter-spacing: -0.075em;
  font-weight: 900;
  text-transform: uppercase;
  color: #f7f1e1;
  text-shadow:
    0 3px 0 rgba(26, 29, 18, 0.24),
    0 16px 42px rgba(0, 0, 0, 0.26);
}

.title span {
  display: inline-block;
}

.title-accent {
  color: var(--gold);
  background: linear-gradient(180deg, #f7dfa8 0%, #e1b66d 58%, #b37f3f 100%);
  -webkit-background-clip: text;
  background-clip: text;
  -webkit-text-fill-color: transparent;
  filter: drop-shadow(0 4px 0 rgba(65, 43, 15, 0.25));
}

.tagline {
  margin: 22px 0 0;
  font-family: var(--display);
  font-size: clamp(19px, 1.7vw, 25px);
  letter-spacing: -0.015em;
  color: #f2e8d2;
  font-weight: 600;
}

.lede {
  margin: 14px 0 0;
  max-width: 500px;
  font-size: 14px;
  line-height: 1.7;
  color: rgba(238, 233, 219, 0.69);
}

.menu-actions {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-wrap: wrap;
  margin-top: clamp(26px, 3.6vh, 38px);
}

.btn {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 9px;
  min-height: 48px;
  padding: 0 22px;
  border: 1px solid transparent;
  border-radius: 10px;
  background: transparent;
  cursor: pointer;
  font-size: 13px;
  font-weight: 700;
  letter-spacing: 0.01em;
  transition: transform 0.18s ease, background 0.18s ease, border-color 0.18s ease, box-shadow 0.18s ease;
  -webkit-tap-highlight-color: transparent;
}

.btn svg {
  width: 18px;
  height: 18px;
  flex: none;
}

.btn:hover {
  transform: translateY(-2px);
}

.btn:active {
  transform: translateY(0);
}

.btn:focus-visible,
.icon-btn:focus-visible,
.switch:focus-visible,
.touch-btn:focus-visible {
  outline: 2px solid var(--gold-bright);
  outline-offset: 3px;
}

.btn-primary {
  min-height: 58px;
  padding: 0 32px;
  background: linear-gradient(180deg, #f4d99c 0%, #dfb46b 100%);
  color: #28220f;
  border-color: rgba(255, 242, 200, 0.6);
  box-shadow:
    0 1px 0 rgba(255, 255, 255, 0.5) inset,
    0 5px 0 #90672f,
    0 16px 34px rgba(0, 0, 0, 0.26);
  font-size: 15px;
  letter-spacing: 0.01em;
}

.btn-primary svg {
  width: 20px;
  height: 20px;
}

.btn-primary:hover {
  background: linear-gradient(180deg, #ffe6ae 0%, #e8bd75 100%);
  box-shadow:
    0 1px 0 rgba(255, 255, 255, 0.6) inset,
    0 5px 0 #90672f,
    0 20px 40px rgba(0, 0, 0, 0.3);
}

.btn-primary:active {
  transform: translateY(3px);
  box-shadow:
    0 1px 0 rgba(255, 255, 255, 0.5) inset,
    0 2px 0 #90672f,
    0 8px 18px rgba(0, 0, 0, 0.25);
}

.btn-ghost {
  background: rgba(18, 23, 15, 0.44);
  border-color: var(--line);
  color: #f1ebdc;
  backdrop-filter: blur(10px);
}

.btn-ghost:hover {
  background: rgba(30, 37, 24, 0.68);
  border-color: var(--line-strong);
}

.btn-quiet {
  color: var(--ink-dim);
}

.btn-quiet:hover {
  color: var(--ink);
  background: rgba(255, 255, 255, 0.05);
}

.btn-compact {
  min-height: 42px;
  padding: 0 22px;
  box-shadow: 0 3px 0 #90672f;
  font-size: 13px;
}

.btn-compact:active {
  box-shadow: 0 1px 0 #90672f;
}

.menu-meta {
  display: flex;
  flex-wrap: wrap;
  gap: 18px;
  margin-top: 24px;
  color: rgba(237, 231, 215, 0.54);
  font-size: 11px;
  letter-spacing: 0.04em;
}

.menu-meta span {
  display: inline-flex;
  align-items: center;
  gap: 7px;
}

.meta-dot {
  width: 5px;
  height: 5px;
  background: var(--moss);
  border-radius: 1px;
  transform: rotate(45deg);
}

.world-card {
  position: relative;
  width: min(330px, 27vw);
  margin-right: clamp(0px, 2vw, 30px);
  align-self: center;
  padding: 22px 22px 20px;
  border: 1px solid var(--line);
  border-radius: 18px;
  background:
    linear-gradient(135deg, rgba(255, 255, 255, 0.055), transparent 40%),
    rgba(14, 18, 11, 0.55);
  backdrop-filter: blur(22px) saturate(1.1);
  box-shadow: 0 30px 70px rgba(0, 0, 0, 0.3);
  animation: card-in 1.1s 0.18s cubic-bezier(0.2, 0.7, 0.2, 1) both;
}

@keyframes card-in {
  from { opacity: 0; transform: translateY(24px); }
  to { opacity: 1; transform: translateY(0); }
}

.world-card::before {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
  padding: 1px;
  background: linear-gradient(140deg, rgba(255, 226, 168, 0.34), transparent 35%, transparent 70%, rgba(255, 255, 255, 0.08));
  -webkit-mask: linear-gradient(#000 0 0) content-box, linear-gradient(#000 0 0);
  -webkit-mask-composite: xor;
  mask-composite: exclude;
  pointer-events: none;
}

.card-topline {
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: 0.18em;
  color: var(--ink-dim);
}

.card-badge {
  color: #a9c77a;
  border: 1px solid rgba(169, 199, 122, 0.25);
  background: rgba(169, 199, 122, 0.08);
  border-radius: 999px;
  padding: 3px 7px;
  font-size: 8px;
}

.world-card h2 {
  margin: 12px 0 7px;
  font-family: var(--display);
  font-size: 25px;
  letter-spacing: -0.03em;
  font-weight: 700;
}

.world-card p {
  margin: 0;
  color: rgba(238, 232, 215, 0.58);
  font-size: 11.5px;
  line-height: 1.65;
}

.world-stats {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 8px;
  margin: 19px 0 16px;
  padding: 14px 0;
  border-top: 1px solid var(--line);
  border-bottom: 1px solid var(--line);
}

.world-stats div {
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.world-stats strong {
  font-family: var(--display);
  font-size: 19px;
  letter-spacing: -0.03em;
  font-weight: 700;
  color: #f1e5c8;
}

.world-stats span {
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--ink-dim);
}

.seed-row {
  display: flex;
  align-items: center;
  gap: 9px;
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: 0.12em;
  color: var(--ink-dim);
}

.seed-row code {
  color: var(--gold);
  font-size: 10px;
  letter-spacing: 0.1em;
}

.seed-hint {
  margin-left: auto;
  font-size: 8px;
  color: rgba(238, 232, 215, 0.34);
}

.card-rule {
  height: 1px;
  background: var(--line);
  margin: 16px 0 14px;
}

.card-tip {
  display: flex;
  gap: 9px;
  color: rgba(238, 232, 215, 0.54);
  font-size: 10.5px;
  line-height: 1.55;
}

.tip-icon {
  color: var(--gold);
}

kbd {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 20px;
  height: 19px;
  padding: 0 5px;
  border: 1px solid rgba(255, 250, 235, 0.19);
  border-bottom-color: rgba(255, 250, 235, 0.3);
  border-radius: 4px;
  background: rgba(255, 255, 255, 0.065);
  color: #efe8d7;
  font-family: var(--mono);
  font-size: 8.5px;
  line-height: 1;
  letter-spacing: 0.02em;
}

.menu-footer {
  display: flex;
  align-items: center;
  gap: 26px;
  flex: none;
  padding-top: 12px;
  color: rgba(237, 231, 215, 0.42);
  font-size: 10px;
  letter-spacing: 0.05em;
}

.footer-hint {
  display: flex;
  align-items: center;
  gap: 7px;
}

.key-cluster {
  display: flex;
  gap: 2px;
}

.footer-hint .key-cluster kbd {
  min-width: 17px;
  height: 17px;
  padding: 0 3px;
  font-size: 7px;
}

.mouse-icon {
  display: inline-block;
  width: 12px;
  height: 17px;
  border: 1px solid rgba(255, 250, 235, 0.3);
  border-radius: 7px;
  position: relative;
}

.mouse-icon::before {
  content: "";
  position: absolute;
  left: 50%;
  top: 3px;
  width: 1px;
  height: 4px;
  background: rgba(255, 250, 235, 0.4);
  transform: translateX(-50%);
}

.hint-sep {
  width: 1px;
  height: 9px;
  background: var(--line);
  margin: 0 2px;
}

.footer-credit {
  margin-left: auto;
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.16em;
  color: rgba(237, 231, 215, 0.28);
}

/* HUD -------------------------------------------------------------------- */
.hud {
  position: absolute;
  inset: 0;
  z-index: 8;
  pointer-events: none;
  transition: opacity 0.3s ease, visibility 0.3s ease;
}

.hud-top {
  position: absolute;
  top: calc(20px + var(--safe-top));
  left: clamp(16px, 2.5vw, 34px);
  right: clamp(16px, 2.5vw, 34px);
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 16px;
}

.hud-location {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 10px 15px 10px 10px;
  border: 1px solid rgba(255, 249, 232, 0.1);
  border-radius: 12px;
  background: rgba(10, 14, 8, 0.38);
  backdrop-filter: blur(14px);
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.18);
}

.hud-compass {
  position: relative;
  width: 38px;
  height: 38px;
  border: 1px solid rgba(255, 245, 220, 0.18);
  border-radius: 50%;
  display: grid;
  place-items: center;
  font-family: var(--mono);
  font-size: 8px;
  color: var(--gold);
  background: radial-gradient(circle, rgba(230, 194, 124, 0.12), transparent 68%);
}

.hud-compass i {
  position: absolute;
  width: 2px;
  height: 9px;
  top: 4px;
  background: var(--gold);
  clip-path: polygon(50% 0, 100% 100%, 0 100%);
}

.hud-zone {
  font-family: var(--mono);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.16em;
  color: #f0e5cc;
}

.hud-mode {
  display: flex;
  align-items: center;
  gap: 6px;
  margin-top: 4px;
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.11em;
  color: rgba(240, 229, 204, 0.45);
}

.mode-dot {
  width: 4px;
  height: 4px;
  border-radius: 50%;
  background: #a8c47b;
}

.hud-stats {
  display: flex;
  gap: 1px;
  border: 1px solid rgba(255, 249, 232, 0.1);
  border-radius: 11px;
  overflow: hidden;
  background: rgba(10, 14, 8, 0.38);
  backdrop-filter: blur(14px);
}

.stat {
  display: flex;
  flex-direction: column;
  gap: 3px;
  min-width: 78px;
  padding: 9px 12px;
  border-left: 1px solid rgba(255, 249, 232, 0.07);
}

.stat:first-child {
  border-left: 0;
}

.stat-label {
  font-family: var(--mono);
  font-size: 7px;
  letter-spacing: 0.14em;
  color: rgba(240, 229, 204, 0.4);
}

.stat strong {
  font-family: var(--mono);
  font-size: 10px;
  font-weight: 600;
  letter-spacing: 0.03em;
  color: #ece3ce;
}

.crosshair {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 26px;
  height: 26px;
  transform: translate(-50%, -50%);
  transition: opacity 0.25s ease;
}

.crosshair-dot {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 3px;
  height: 3px;
  transform: translate(-50%, -50%);
  border-radius: 50%;
  background: rgba(255, 252, 241, 0.94);
  box-shadow: 0 0 0 1px rgba(15, 18, 11, 0.3), 0 0 8px rgba(255, 250, 232, 0.5);
}

.crosshair-ring {
  position: absolute;
  inset: 3px;
  border: 1px solid rgba(255, 250, 238, 0.18);
  border-radius: 50%;
  transform: scale(0.8);
  opacity: 0;
  transition: opacity 0.2s ease, transform 0.2s ease;
}

.crosshair.is-target .crosshair-ring {
  opacity: 1;
  transform: scale(1);
}

.crosshair.is-target .crosshair-dot {
  background: var(--gold-bright);
}

.target-label {
  position: absolute;
  left: 50%;
  top: calc(50% + 32px);
  transform: translateX(-50%);
  padding: 5px 9px;
  border: 1px solid rgba(255, 249, 232, 0.13);
  border-radius: 5px;
  background: rgba(10, 14, 8, 0.52);
  backdrop-filter: blur(10px);
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.09em;
  text-transform: uppercase;
  color: rgba(242, 234, 215, 0.7);
  transition: opacity 0.2s ease, transform 0.2s ease;
}

.block-label {
  position: absolute;
  left: 50%;
  bottom: calc(110px + var(--safe-bottom));
  transform: translateX(-50%);
  padding: 6px 12px;
  border: 1px solid rgba(255, 249, 232, 0.13);
  border-radius: 999px;
  background: rgba(10, 14, 8, 0.55);
  backdrop-filter: blur(12px);
  font-size: 10px;
  font-weight: 600;
  letter-spacing: 0.04em;
  color: #f1e6cd;
  white-space: nowrap;
  transition: opacity 0.25s ease, transform 0.25s ease;
}

.block-label.is-hidden {
  opacity: 0 !important;
  transform: translate(-50%, 4px);
}

.hotbar {
  position: absolute;
  left: 50%;
  bottom: calc(26px + var(--safe-bottom));
  transform: translateX(-50%);
  display: flex;
  align-items: flex-end;
  gap: 5px;
  padding: 7px;
  border: 1px solid rgba(255, 249, 232, 0.12);
  border-radius: 14px;
  background: rgba(9, 13, 7, 0.55);
  backdrop-filter: blur(18px) saturate(1.1);
  box-shadow: 0 16px 40px rgba(0, 0, 0, 0.28);
  pointer-events: auto;
}

.hotbar-slot {
  position: relative;
  width: 52px;
  height: 52px;
  padding: 0;
  border: 1px solid transparent;
  border-radius: 9px;
  background: rgba(255, 255, 255, 0.035);
  cursor: pointer;
  transition: transform 0.18s cubic-bezier(0.2, 0.7, 0.2, 1), background 0.18s ease, border-color 0.18s ease, box-shadow 0.18s ease;
  -webkit-tap-highlight-color: transparent;
}

.hotbar-slot:hover {
  background: rgba(255, 255, 255, 0.08);
}

.hotbar-slot canvas {
  width: 100%;
  height: 100%;
  display: block;
  image-rendering: pixelated;
}

.hotbar-slot .slot-key {
  position: absolute;
  left: 5px;
  top: 4px;
  font-family: var(--mono);
  font-size: 7px;
  color: rgba(255, 249, 232, 0.4);
}

.hotbar-slot.is-selected {
  border-color: rgba(244, 215, 149, 0.72);
  background: rgba(230, 194, 124, 0.13);
  transform: translateY(-6px);
  box-shadow:
    0 0 0 1px rgba(244, 215, 149, 0.2),
    0 0 22px rgba(230, 194, 124, 0.2),
    0 12px 22px rgba(0, 0, 0, 0.3);
}

.hotbar-slot.is-selected .slot-key {
  color: var(--gold-bright);
}

.hint-strip {
  position: absolute;
  left: 50%;
  bottom: calc(98px + var(--safe-bottom));
  transform: translateX(-50%);
  display: flex;
  align-items: center;
  gap: 15px;
  white-space: nowrap;
  padding: 7px 14px;
  border: 1px solid rgba(255, 249, 232, 0.08);
  border-radius: 999px;
  background: rgba(9, 13, 7, 0.34);
  backdrop-filter: blur(10px);
  font-size: 8.5px;
  letter-spacing: 0.04em;
  color: rgba(242, 234, 215, 0.54);
  transition: opacity 0.7s ease, transform 0.7s ease;
}

.hint-strip kbd {
  min-width: 17px;
  height: 16px;
  font-size: 7px;
  padding: 0 4px;
}

.hint-strip.is-faded {
  opacity: 0;
  transform: translate(-50%, 8px);
}

.mobile-controls {
  display: none;
}

/* Overlays --------------------------------------------------------------- */
.overlay {
  z-index: 20;
  display: grid;
  place-items: center;
  padding: 20px;
  background: rgba(5, 8, 4, 0.58);
  backdrop-filter: blur(9px) saturate(0.9);
}

.modal {
  position: relative;
  width: min(720px, calc(100vw - 32px));
  border: 1px solid rgba(255, 249, 232, 0.14);
  border-radius: 18px;
  background:
    linear-gradient(135deg, rgba(255, 255, 255, 0.055), transparent 34%),
    linear-gradient(180deg, rgba(26, 32, 21, 0.98), rgba(16, 21, 13, 0.99));
  box-shadow: var(--shadow), 0 0 0 1px rgba(0, 0, 0, 0.32) inset;
  overflow: hidden;
  animation: modal-in 0.38s cubic-bezier(0.2, 0.8, 0.2, 1) both;
}

@keyframes modal-in {
  from { opacity: 0; transform: translateY(16px) scale(0.985); }
  to { opacity: 1; transform: translateY(0) scale(1); }
}

.modal::before {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
  padding: 1px;
  background: linear-gradient(130deg, rgba(255, 226, 168, 0.3), transparent 30%, transparent 70%, rgba(255, 255, 255, 0.06));
  -webkit-mask: linear-gradient(#000 0 0) content-box, linear-gradient(#000 0 0);
  -webkit-mask-composite: xor;
  mask-composite: exclude;
  pointer-events: none;
}

.modal-kicker {
  font-family: var(--mono);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.2em;
  color: var(--gold);
}

.pause-modal {
  width: min(430px, calc(100vw - 32px));
  padding: 32px;
  text-align: center;
}

.pause-modal h2,
.settings-head h2 {
  margin: 10px 0 0;
  font-family: var(--display);
  font-size: 34px;
  line-height: 1;
  letter-spacing: -0.04em;
  font-weight: 800;
}

.modal-sub {
  margin: 12px auto 0;
  max-width: 300px;
  font-size: 12px;
  line-height: 1.6;
  color: rgba(238, 232, 215, 0.55);
}

.pause-actions {
  display: flex;
  flex-direction: column;
  gap: 8px;
  margin: 26px 0 24px;
}

.pause-actions .btn {
  width: 100%;
}

.pause-foot {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 10px;
  padding-top: 18px;
  border-top: 1px solid var(--line);
}

.pause-foot div {
  display: flex;
  flex-direction: column;
  gap: 5px;
}

.pause-foot span {
  font-family: var(--mono);
  font-size: 7px;
  letter-spacing: 0.13em;
  color: var(--ink-dim);
}

.pause-foot code {
  font-family: var(--mono);
  font-size: 9px;
  color: #e9dec6;
}

.settings-modal {
  width: min(720px, calc(100vw - 32px));
  max-height: min(88vh, 900px);
  display: flex;
  flex-direction: column;
}

.settings-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 16px;
  padding: 26px 28px 20px;
  border-bottom: 1px solid var(--line);
}

.settings-head h2 {
  font-size: 30px;
}

.icon-btn {
  display: grid;
  place-items: center;
  width: 36px;
  height: 36px;
  flex: none;
  border: 1px solid var(--line);
  border-radius: 9px;
  background: rgba(255, 255, 255, 0.035);
  cursor: pointer;
  transition: background 0.18s ease, border-color 0.18s ease;
}

.icon-btn:hover {
  background: rgba(255, 255, 255, 0.08);
  border-color: var(--line-strong);
}

.icon-btn svg {
  width: 17px;
  height: 17px;
}

.settings-scroll {
  overflow-y: auto;
  padding: 4px 28px 8px;
  scrollbar-width: thin;
  scrollbar-color: rgba(230, 194, 124, 0.25) transparent;
}

.settings-scroll::-webkit-scrollbar {
  width: 8px;
}

.settings-scroll::-webkit-scrollbar-thumb {
  background: rgba(230, 194, 124, 0.22);
  border-radius: 999px;
}

.setting-group {
  padding: 18px 0 8px;
}

.setting-group + .setting-group {
  border-top: 1px solid var(--line);
}

.group-title {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-bottom: 8px;
  font-family: var(--mono);
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0.19em;
  color: var(--gold);
}

.group-title i {
  height: 1px;
  flex: 1;
  background: linear-gradient(90deg, var(--line), transparent);
}

.setting-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
  padding: 13px 0;
}

.setting-copy {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.setting-copy label {
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 0.01em;
  color: #f0e7d4;
}

.setting-copy span {
  font-size: 10px;
  line-height: 1.4;
  color: rgba(238, 232, 215, 0.43);
}

.setting-control {
  display: flex;
  align-items: center;
  gap: 12px;
  width: 210px;
  flex: none;
}

.setting-control output {
  width: 64px;
  flex: none;
  text-align: right;
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: 0.03em;
  color: var(--gold-bright);
}

input[type="range"] {
  -webkit-appearance: none;
  appearance: none;
  width: 100%;
  height: 20px;
  margin: 0;
  background: transparent;
  cursor: pointer;
}

input[type="range"]::-webkit-slider-runnable-track {
  height: 3px;
  border-radius: 999px;
  background: linear-gradient(90deg, var(--gold) var(--fill, 50%), rgba(255, 255, 255, 0.12) var(--fill, 50%));
}

input[type="range"]::-moz-range-track {
  height: 3px;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.12);
}

input[type="range"]::-moz-range-progress {
  height: 3px;
  border-radius: 999px;
  background: var(--gold);
}

input[type="range"]::-webkit-slider-thumb {
  -webkit-appearance: none;
  appearance: none;
  width: 13px;
  height: 13px;
  margin-top: -5px;
  border-radius: 50%;
  border: 2px solid #171d12;
  background: var(--gold-bright);
  box-shadow: 0 0 0 1px rgba(244, 215, 149, 0.4), 0 2px 8px rgba(0, 0, 0, 0.35);
  transition: transform 0.15s ease;
}

input[type="range"]:hover::-webkit-slider-thumb {
  transform: scale(1.15);
}

input[type="range"]::-moz-range-thumb {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  border: 2px solid #171d12;
  background: var(--gold-bright);
}

select {
  width: 100%;
  height: 34px;
  padding: 0 30px 0 10px;
  border: 1px solid var(--line);
  border-radius: 7px;
  background: rgba(255, 255, 255, 0.05);
  color: #ece2cc;
  font-size: 11px;
  outline: none;
  cursor: pointer;
}

select option {
  background: #171d12;
  color: #ece2cc;
}

.switch {
  position: relative;
  width: 42px;
  height: 24px;
  flex: none;
  padding: 0;
  border: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.06);
  cursor: pointer;
  transition: background 0.2s ease, border-color 0.2s ease;
}

.switch span {
  position: absolute;
  top: 3px;
  left: 3px;
  width: 16px;
  height: 16px;
  border-radius: 50%;
  background: rgba(255, 250, 238, 0.45);
  transition: transform 0.2s cubic-bezier(0.2, 0.8, 0.2, 1), background 0.2s ease;
}

.switch.is-on {
  background: rgba(230, 194, 124, 0.25);
  border-color: rgba(230, 194, 124, 0.44);
}

.switch.is-on span {
  transform: translateX(18px);
  background: var(--gold-bright);
}

.settings-foot {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: 16px 28px 20px;
  border-top: 1px solid var(--line);
