/* Toast ------------------------------------------------------------------ */
.toast {
  position: absolute;
  left: 50%;
  top: calc(24px + var(--safe-top));
  z-index: 30;
  transform: translate(-50%, -12px);
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 10px 16px;
  border: 1px solid rgba(255, 249, 232, 0.14);
  border-radius: 999px;
  background: rgba(14, 19, 11, 0.82);
  backdrop-filter: blur(16px);
  box-shadow: 0 12px 30px rgba(0, 0, 0, 0.28);
  color: #f0e6d0;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.02em;
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
  transition: opacity 0.3s ease, transform 0.3s ease, visibility 0.3s ease;
}

