export class AudioManager {
  constructor(settings) {
    this.settings = settings;
    this.ctx = null;
    this.master = null;
    this.ambientGain = null;
    this.noiseBuffer = null;
    this.ambientStarted = false;
    this.birdTimer = null;
  }

  unlock() {
    if (this.ctx) {
      if (this.ctx.state === 'suspended') this.ctx.resume();
      return;
    }
    const AudioContext = window.AudioContext || window.webkitAudioContext;
    if (!AudioContext) return;
    this.ctx = new AudioContext();
    this.master = this.ctx.createGain();
    this.master.gain.value = this.settings.volume ?? 0.7;
    this.master.connect(this.ctx.destination);
    this.noiseBuffer = this.createNoiseBuffer(2.5);
    this.startAmbient();
  }

  createNoiseBuffer(seconds) {
    const length = Math.floor(this.ctx.sampleRate * seconds);
    const buffer = this.ctx.createBuffer(1, length, this.ctx.sampleRate);
    const data = buffer.getChannelData(0);
    let last = 0;
    for (let i = 0; i < length; i += 1) {
      const white = Math.random() * 2 - 1;
      last = (last + 0.02 * white) / 1.02;
      data[i] = last * 3.4;
    }
    return buffer;
  }

  setVolume(value) {
    this.settings.volume = value;
    if (!this.master || !this.ctx) return;
    this.master.gain.setTargetAtTime(value, this.ctx.currentTime, 0.06);
  }

  setAmbient(enabled) {
    this.settings.ambient = enabled;
    if (!this.ambientGain || !this.ctx) return;
    this.ambientGain.gain.setTargetAtTime(enabled ? 0.055 : 0, this.ctx.currentTime, 0.8);
  }

  startAmbient() {
    if (this.ambientStarted || !this.ctx) return;
    this.ambientStarted = true;
    const source = this.ctx.createBufferSource();
    source.buffer = this.noiseBuffer;
    source.loop = true;
    const filter = this.ctx.createBiquadFilter();
    filter.type = 'lowpass';
    filter.frequency.value = 620;
    filter.Q.value = 0.3;
    this.ambientGain = this.ctx.createGain();
    this.ambientGain.gain.value = this.settings.ambient === false ? 0 : 0.055;
    source.connect(filter);
    filter.connect(this.ambientGain);
    this.ambientGain.connect(this.master);
    source.start();
    this.scheduleBird();
  }

  scheduleBird() {
    clearTimeout(this.birdTimer);
    this.birdTimer = setTimeout(() => {
      if (this.settings.ambient !== false && this.ctx?.state === 'running') this.bird();
      this.scheduleBird();
    }, 6000 + Math.random() * 11000);
  }

  bird() {
    if (!this.ctx) return;
    const now = this.ctx.currentTime;
    const base = 1450 + Math.random() * 850;
    for (let i = 0; i < 2 + Math.floor(Math.random() * 3); i += 1) {
      const osc = this.ctx.createOscillator();
      const gain = this.ctx.createGain();
      osc.type = 'sine';
      osc.frequency.setValueAtTime(base * (1 + i * 0.08), now + i * 0.09);
      osc.frequency.exponentialRampToValueAtTime(base * 1.45, now + i * 0.09 + 0.05);
      gain.gain.setValueAtTime(0.0001, now + i * 0.09);
      gain.gain.exponentialRampToValueAtTime(0.012, now + i * 0.09 + 0.012);
      gain.gain.exponentialRampToValueAtTime(0.0001, now + i * 0.09 + 0.1);
      osc.connect(gain);
      gain.connect(this.master);
      osc.start(now + i * 0.09);
      osc.stop(now + i * 0.09 + 0.13);
    }
  }

  tone(frequency, duration, gainValue, type = 'sine', slide = 0) {
    if (!this.ctx || this.ctx.state !== 'running') return;
    const now = this.ctx.currentTime;
    const osc = this.ctx.createOscillator();
    const gain = this.ctx.createGain();
    osc.type = type;
    osc.frequency.setValueAtTime(frequency, now);
    if (slide) osc.frequency.exponentialRampToValueAtTime(Math.max(30, frequency + slide), now + duration);
    gain.gain.setValueAtTime(0.0001, now);
    gain.gain.exponentialRampToValueAtTime(gainValue, now + 0.008);
    gain.gain.exponentialRampToValueAtTime(0.0001, now + duration);
    osc.connect(gain);
    gain.connect(this.master);
    osc.start(now);
    osc.stop(now + duration + 0.02);
  }

  noise(duration, frequency, gainValue, type = 'bandpass') {
    if (!this.ctx || this.ctx.state !== 'running' || !this.noiseBuffer) return;
    const now = this.ctx.currentTime;
    const source = this.ctx.createBufferSource();
    source.buffer = this.noiseBuffer;
    const filter = this.ctx.createBiquadFilter();
    filter.type = type;
    filter.frequency.value = frequency;
    filter.Q.value = 0.7;
    const gain = this.ctx.createGain();
    gain.gain.setValueAtTime(0.0001, now);
    gain.gain.exponentialRampToValueAtTime(gainValue, now + 0.008);
    gain.gain.exponentialRampToValueAtTime(0.0001, now + duration);
    source.connect(filter);
    filter.connect(gain);
    gain.connect(this.master);
    source.start(now);
    source.stop(now + duration + 0.02);
  }

  click() {
    this.tone(520, 0.045, 0.03, 'triangle', 120);
  }

  select() {
    this.tone(420, 0.055, 0.022, 'triangle', 80);
  }

  breakBlock() {
    this.noise(0.18, 680, 0.12, 'bandpass');
    this.tone(112, 0.13, 0.07, 'sine', -35);
  }

  placeBlock() {
    this.tone(118, 0.1, 0.09, 'sine', -30);
    this.noise(0.06, 900, 0.035, 'highpass');
  }

  step() {
    this.noise(0.075, 330, 0.026, 'lowpass');
  }

  jump() {
    this.tone(210, 0.08, 0.03, 'sine', 40);
  }

  denied() {
    this.tone(140, 0.14, 0.04, 'square', -20);
  }

  whoosh() {
    this.noise(0.22, 1200, 0.045, 'bandpass');
  }

  save() {
    this.tone(660, 0.09, 0.03, 'sine');
    setTimeout(() => this.tone(880, 0.14, 0.025, 'sine'), 70);
  }
}

import * as THREE from 'three';

const _matrix = new THREE.Matrix4();
const _position = new THREE.Vector3();
const _quaternion = new THREE.Quaternion();
const _scale = new THREE.Vector3();
const _euler = new THREE.Euler();
const _color = new THREE.Color();

export class BlockParticles {
  constructor(scene, count = 180) {
    this.count = count;
    this.items = new Array(count).fill(null);
    this.cursor = 0;
    const geometry = new THREE.BoxGeometry(0.13, 0.13, 0.13);
    const material = new THREE.MeshStandardMaterial({
      roughness: 0.92,
      metalness: 0,
      vertexColors: false,
    });
    this.mesh = new THREE.InstancedMesh(geometry, material, count);
    this.mesh.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
    this.mesh.frustumCulled = false;
    this.mesh.castShadow = false;
    this.mesh.receiveShadow = false;
    scene.add(this.mesh);
    for (let i = 0; i < count; i += 1) {
      _matrix.makeScale(0, 0, 0);
      this.mesh.setMatrixAt(i, _matrix);
      this.mesh.setColorAt(i, _color.set(0xffffff));
    }
    this.mesh.instanceMatrix.needsUpdate = true;
    if (this.mesh.instanceColor) this.mesh.instanceColor.needsUpdate = true;
  }

  spawnBurst(x, y, z, color, amount = 16) {
    for (let i = 0; i < amount; i += 1) {
      const index = this.cursor;
      this.cursor = (this.cursor + 1) % this.count;
      const angle = Math.random() * Math.PI * 2;
      const speed = 0.7 + Math.random() * 2.4;
      const item = {
        x: x + 0.5 + (Math.random() - 0.5) * 0.6,
        y: y + 0.5 + (Math.random() - 0.5) * 0.6,
        z: z + 0.5 + (Math.random() - 0.5) * 0.6,
        vx: Math.cos(angle) * speed * 0.55,
        vy: 1.2 + Math.random() * 2.4,
        vz: Math.sin(angle) * speed * 0.55,
        life: 0.55 + Math.random() * 0.55,
        maxLife: 1.1,
        size: 0.45 + Math.random() * 0.8,
        rot: Math.random() * Math.PI,
        spin: (Math.random() - 0.5) * 10,
      };
      this.items[index] = item;
      const base = new THREE.Color(color);
      base.offsetHSL((Math.random() - 0.5) * 0.035, 0, (Math.random() - 0.5) * 0.13);
      this.mesh.setColorAt(index, base);
    }
    if (this.mesh.instanceColor) this.mesh.instanceColor.needsUpdate = true;
  }

  spawnPlace(x, y, z, color) {
    for (let i = 0; i < 7; i += 1) {
      const index = this.cursor;
      this.cursor = (this.cursor + 1) % this.count;
      this.items[index] = {
        x: x + 0.5 + (Math.random() - 0.5) * 0.9,
        y: y + 0.05,
        z: z + 0.5 + (Math.random() - 0.5) * 0.9,
        vx: (Math.random() - 0.5) * 0.6,
        vy: 0.4 + Math.random() * 0.9,
        vz: (Math.random() - 0.5) * 0.6,
        life: 0.32 + Math.random() * 0.24,
        maxLife: 0.56,
        size: 0.3 + Math.random() * 0.4,
        rot: Math.random() * Math.PI,
        spin: (Math.random() - 0.5) * 8,
      };
      this.mesh.setColorAt(index, _color.set(color).offsetHSL(0, 0, (Math.random() - 0.5) * 0.1));
    }
    if (this.mesh.instanceColor) this.mesh.instanceColor.needsUpdate = true;
  }

  update(dt) {
    let changed = false;
    for (let i = 0; i < this.count; i += 1) {
      const item = this.items[i];
      if (!item) continue;
      changed = true;
      item.life -= dt;
      if (item.life <= 0) {
        this.items[i] = null;
        _matrix.makeScale(0, 0, 0);
        this.mesh.setMatrixAt(i, _matrix);
        continue;
      }
      item.vy -= 14 * dt;
      item.x += item.vx * dt;
      item.y += item.vy * dt;
      item.z += item.vz * dt;
      item.rot += item.spin * dt;
      if (item.y < 0) {
        item.y = 0;
        item.vy *= -0.25;
        item.vx *= 0.7;
        item.vz *= 0.7;
      }
      const fade = Math.min(1, item.life / 0.32);
      const size = item.size * fade;
      _position.set(item.x, item.y, item.z);
      _euler.set(item.rot, item.rot * 0.7, item.rot * 0.4);
      _quaternion.setFromEuler(_euler);
      _scale.set(size, size, size);
      _matrix.compose(_position, _quaternion, _scale);
      this.mesh.setMatrixAt(i, _matrix);
    }
    if (changed) this.mesh.instanceMatrix.needsUpdate = true;
  }
}

export class SmokeSystem {
  constructor(scene, count = 80) {
    this.count = count;
    this.items = new Array(count).fill(null);
    this.cursor = 0;
    this.timer = 0;
    const geometry = new THREE.BoxGeometry(0.2, 0.2, 0.2);
    const material = new THREE.MeshBasicMaterial({
      color: 0xcac6b9,
      transparent: true,
      opacity: 0.2,
      depthWrite: false,
      fog: true,
    });
    this.mesh = new THREE.InstancedMesh(geometry, material, count);
    this.mesh.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
    this.mesh.frustumCulled = false;
    scene.add(this.mesh);
    for (let i = 0; i < count; i += 1) {
      _matrix.makeScale(0, 0, 0);
      this.mesh.setMatrixAt(i, _matrix);
    }
    this.mesh.instanceMatrix.needsUpdate = true;
  }

  update(dt, emitter, enabled = true) {
    this.timer -= dt;
    if (enabled && emitter && this.timer <= 0) {
      this.timer = 0.16 + Math.random() * 0.12;
      const index = this.cursor;
      this.cursor = (this.cursor + 1) % this.count;
      this.items[index] = {
        x: emitter.x + (Math.random() - 0.5) * 0.5,
        y: emitter.y,
        z: emitter.z + (Math.random() - 0.5) * 0.5,
        vx: (Math.random() - 0.5) * 0.2,
        vy: 0.35 + Math.random() * 0.45,
        vz: (Math.random() - 0.5) * 0.2,
        life: 3.2 + Math.random() * 2.4,
        maxLife: 5.6,
        size: 0.7 + Math.random() * 0.6,
        rot: Math.random() * Math.PI,
        spin: (Math.random() - 0.5) * 0.5,
      };
    }

    let changed = false;
    for (let i = 0; i < this.count; i += 1) {
      const item = this.items[i];
      if (!item) continue;
      changed = true;
      item.life -= dt;
      if (item.life <= 0) {
        this.items[i] = null;
        _matrix.makeScale(0, 0, 0);
        this.mesh.setMatrixAt(i, _matrix);
        continue;
      }
      item.x += item.vx * dt;
      item.y += item.vy * dt;
      item.z += item.vz * dt;
      item.vx += Math.sin(item.y * 1.7 + i) * 0.012 * dt;
      item.vz += Math.cos(item.y * 1.2 + i) * 0.01 * dt;
      item.rot += item.spin * dt;
      const age = item.maxLife - item.life;
      const fade = Math.min(1, age / 0.5) * Math.min(1, item.life / 1.3);
      const size = item.size * (0.7 + age * 0.55) * fade;
      _position.set(item.x, item.y, item.z);
      _euler.set(item.rot, item.rot * 0.6, item.rot * 0.3);
      _quaternion.setFromEuler(_euler);
      _scale.set(size, size, size);
      _matrix.compose(_position, _quaternion, _scale);
      this.mesh.setMatrixAt(i, _matrix);
    }
    if (changed) this.mesh.instanceMatrix.needsUpdate = true;
  }
}

export class Motes {
  constructor(scene, count = 110) {
    this.count = count;
    this.group = new THREE.Group();
    scene.add(this.group);
    const geometry = new THREE.BoxGeometry(0.032, 0.032, 0.032);
    const material = new THREE.MeshBasicMaterial({
      color: 0xffdda0,
      transparent: true,
      opacity: 0.46,
      blending: THREE.AdditiveBlending,
      depthWrite: false,
      fog: false,
    });
    this.mesh = new THREE.InstancedMesh(geometry, material, count);
    this.mesh.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
    this.mesh.frustumCulled = false;
    this.group.add(this.mesh);
    this.items = [];
    for (let i = 0; i < count; i += 1) {
      this.items.push({
        x: (Math.random() - 0.5) * 36,
        y: 1 + Math.random() * 17,
        z: (Math.random() - 0.5) * 36,
        phase: Math.random() * Math.PI * 2,
        speed: 0.1 + Math.random() * 0.25,
        scale: 0.6 + Math.random() * 1.5,
      });
    }
    this.group.position.set(0, 0, 0);
    this.time = 0;
  }

  update(dt, cameraPosition) {
    this.time += dt;
    this.group.position.x = THREE.MathUtils.lerp(this.group.position.x, cameraPosition.x, 0.025);
    this.group.position.z = THREE.MathUtils.lerp(this.group.position.z, cameraPosition.z, 0.025);
    for (let i = 0; i < this.count; i += 1) {
      const item = this.items[i];
      const x = item.x + Math.sin(this.time * item.speed + item.phase) * 0.65;
      const y = item.y + Math.sin(this.time * item.speed * 1.7 + item.phase * 1.4) * 0.7;
      const z = item.z + Math.cos(this.time * item.speed * 0.8 + item.phase) * 0.65;
      const twinkle = 0.45 + 0.55 * Math.abs(Math.sin(this.time * 0.7 + item.phase));
      const size = item.scale * twinkle;
      _position.set(x, y, z);
      _quaternion.set(0, 0, 0, 1);
      _scale.set(size, size, size);
      _matrix.compose(_position, _quaternion, _scale);
      this.mesh.setMatrixAt(i, _matrix);
    }
    this.mesh.instanceMatrix.needsUpdate = true;
  }
}

import * as THREE from 'three';

const SKY_VERTEX = `
  varying vec3 vWorldPosition;
  void main() {
    vec4 worldPosition = modelMatrix * vec4(position, 1.0);
    vWorldPosition = worldPosition.xyz;
    gl_Position = projectionMatrix * viewMatrix * worldPosition;
  }
`;

const SKY_FRAGMENT = `
  uniform vec3 topColor;
  uniform vec3 horizonColor;
  uniform vec3 groundColor;
  uniform vec3 sunColor;
  uniform vec3 sunDirection;
  varying vec3 vWorldPosition;
  void main() {
    vec3 direction = normalize(vWorldPosition - cameraPosition);
    float height = direction.y;
    vec3 color;
    if (height > 0.0) {
      color = mix(horizonColor, topColor, pow(clamp(height, 0.0, 1.0), 0.58));
    } else {
      color = mix(horizonColor, groundColor, clamp(-height * 2.8, 0.0, 1.0));
    }
    float sunAmount = max(dot(direction, sunDirection), 0.0);
    color += sunColor * pow(sunAmount, 220.0) * 1.5;
    color += sunColor * pow(sunAmount, 8.0) * 0.11;
    float haze = smoothstep(-0.05, 0.32, height) * (1.0 - smoothstep(0.05, 0.65, height));
    color += vec3(0.14, 0.075, 0.03) * haze;
    gl_FragColor = vec4(color, 1.0);
  }
`;

function seededRandom(seed) {
  let value = seed;
  return () => {
    value = (value * 1664525 + 1013904223) % 4294967296;
    return value / 4294967296;
  };
}

export class Environment {
  constructor(scene, renderer, settings = {}) {
    this.scene = scene;
    this.renderer = renderer;
    this.settings = settings;
    this.sunDirection = new THREE.Vector3(-0.62, 0.44, 0.34).normalize();
    this.focus = new THREE.Vector3();
    this.time = 0;

    this.setupSky();
    this.setupLights();
    this.setupClouds();
    this.setupSun();
    this.scene.fog = new THREE.Fog(0xdfb084, 55, 148);
    this.setQuality(settings.quality ?? 'high');
  }

  setupSky() {
    this.skyMaterial = new THREE.ShaderMaterial({
      uniforms: {
        topColor: { value: new THREE.Color(0x4c7da9) },
        horizonColor: { value: new THREE.Color(0xf6b873) },
        groundColor: { value: new THREE.Color(0x625f51) },
        sunColor: { value: new THREE.Color(0xffdda0) },
        sunDirection: { value: this.sunDirection },
      },
      vertexShader: SKY_VERTEX,
      fragmentShader: SKY_FRAGMENT,
      side: THREE.BackSide,
      depthWrite: false,
      fog: false,
    });
    this.sky = new THREE.Mesh(new THREE.BoxGeometry(680, 680, 680), this.skyMaterial);
    this.sky.renderOrder = -1000;
    this.sky.frustumCulled = false;
    this.scene.add(this.sky);
  }

  setupSun() {
    this.sunGroup = new THREE.Group();
    const core = new THREE.Mesh(
      new THREE.BoxGeometry(11, 11, 11),
      new THREE.MeshBasicMaterial({ color: 0xfff1c8, toneMapped: false })
    );
    const innerGlow = new THREE.Mesh(
      new THREE.BoxGeometry(22, 22, 22),
      new THREE.MeshBasicMaterial({
        color: 0xffcc7e,
        transparent: true,
        opacity: 0.19,
        blending: THREE.AdditiveBlending,
        depthWrite: false,
        toneMapped: false,
      })
    );
    const outerGlow = new THREE.Mesh(
      new THREE.BoxGeometry(40, 40, 40),
      new THREE.MeshBasicMaterial({
        color: 0xffad58,
        transparent: true,
        opacity: 0.065,
        blending: THREE.AdditiveBlending,
        depthWrite: false,
        toneMapped: false,
      })
    );
    this.sunGroup.add(outerGlow, innerGlow, core);
    this.sunGroup.renderOrder = -900;
    this.scene.add(this.sunGroup);
  }

  setupLights() {
    this.hemisphere = new THREE.HemisphereLight(0xc9def2, 0x55452e, 1.3);
    this.scene.add(this.hemisphere);

    this.sun = new THREE.DirectionalLight(0xffd19a, 3.1);
    this.sun.castShadow = true;
    this.sun.shadow.mapSize.set(2048, 2048);
    this.sun.shadow.camera.left = -52;
    this.sun.shadow.camera.right = 52;
    this.sun.shadow.camera.top = 52;
    this.sun.shadow.camera.bottom = -52;
    this.sun.shadow.camera.near = 1;
    this.sun.shadow.camera.far = 240;
    this.sun.shadow.bias = -0.00045;
    this.sun.shadow.normalBias = 0.035;
    this.sun.target.position.set(0, 18, 0);
    this.scene.add(this.sun);
    this.scene.add(this.sun.target);

    this.fill = new THREE.DirectionalLight(0x9db7d4, 0.4);
    this.fill.position.set(55, 40, -60);
    this.scene.add(this.fill);

    this.bounce = new THREE.AmbientLight(0xffe4bb, 0.12);
    this.scene.add(this.bounce);
  }

  setupClouds() {
    const random = seededRandom(9417);
    const puffs = [];
    for (let cluster = 0; cluster < 24; cluster += 1) {
      const cx = (random() - 0.5) * 300;
      const cz = (random() - 0.5) * 300;
      const cy = 53 + random() * 18;
      const count = 3 + Math.floor(random() * 5);
      for (let i = 0; i < count; i += 1) {
        puffs.push({
          x: cx + (random() - 0.5) * 28,
          y: cy + (random() - 0.5) * 4,
          z: cz + (random() - 0.5) * 18,
          sx: 4 + random() * 11,
          sy: 1.2 + random() * 1.8,
          sz: 3 + random() * 8,
          speed: 0.22 + random() * 0.18,
          tint: 0.9 + random() * 0.1,
        });
      }
    }
    this.cloudPuffs = puffs;
    const geometry = new THREE.BoxGeometry(1, 1, 1);
    const material = new THREE.MeshStandardMaterial({
      color: 0xfff2df,
      roughness: 1,
      metalness: 0,
      transparent: true,
      opacity: 0.72,
      depthWrite: false,
      fog: true,
    });
    this.clouds = new THREE.InstancedMesh(geometry, material, puffs.length);
    this.clouds.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
    this.clouds.frustumCulled = false;
    this.clouds.castShadow = false;
    this.clouds.receiveShadow = false;
    const color = new THREE.Color();
    puffs.forEach((puff, index) => {
      color.setRGB(puff.tint, puff.tint * 0.97, puff.tint * 0.92);
      this.clouds.setColorAt(index, color);
    });
    if (this.clouds.instanceColor) this.clouds.instanceColor.needsUpdate = true;
    this.scene.add(this.clouds);
    this.cloudMatrix = new THREE.Matrix4();
    this.cloudQuat = new THREE.Quaternion();
    this.cloudScale = new THREE.Vector3();
    this.cloudPosition = new THREE.Vector3();
    this.updateClouds(0);
  }

  updateClouds(dt) {
    for (let i = 0; i < this.cloudPuffs.length; i += 1) {
      const puff = this.cloudPuffs[i];
      puff.x += puff.speed * dt;
      if (puff.x > 165) puff.x = -165;
      this.cloudPosition.set(puff.x, puff.y, puff.z);
      this.cloudScale.set(puff.sx, puff.sy, puff.sz);
      this.cloudMatrix.compose(this.cloudPosition, this.cloudQuat, this.cloudScale);
      this.clouds.setMatrixAt(i, this.cloudMatrix);
    }
    this.clouds.instanceMatrix.needsUpdate = true;
  }

  addPointLights(lights = []) {
    this.pointLights = [];
    lights.forEach((config) => {
      const light = new THREE.PointLight(config.color ?? 0xffb568, config.intensity ?? 8, config.distance ?? 10, 2);
      light.position.set(config.x, config.y, config.z);
      this.scene.add(light);
      this.pointLights.push(light);
    });
  }

  setQuality(quality) {
    this.quality = quality;
    if (quality === 'high') {
      this.sun.shadow.mapSize.set(2048, 2048);
    } else if (quality === 'balanced') {
      this.sun.shadow.mapSize.set(1536, 1536);
    } else {
      this.sun.shadow.mapSize.set(1024, 1024);
    }
    if (this.sun.shadow.map) {
      this.sun.shadow.map.dispose();
      this.sun.shadow.map = null;
    }
  }

  setShadows(enabled) {
    this.sun.castShadow = enabled;
    this.renderer.shadowMap.enabled = enabled;
    this.sun.shadow.needsUpdate = true;
  }

  update(dt, camera, focus) {
    this.time += dt;
    if (focus) this.focus.copy(focus);
    this.sky.position.copy(camera.position);
    this.sunGroup.position.copy(camera.position).addScaledVector(this.sunDirection, 260);
    this.sun.target.position.set(this.focus.x, this.focus.y + 6, this.focus.z);
    this.sun.target.updateMatrixWorld();
    this.sun.position.copy(this.sun.target.position).addScaledVector(this.sunDirection, 120);
    this.fill.position.set(this.focus.x + 55, this.focus.y + 40, this.focus.z - 60);
    this.updateClouds(dt);
    if (this.pointLights) {
      this.pointLights.forEach((light, index) => {
        light.intensity = (this.pointLights[index].userData?.base ?? light.intensity) * (0.96 + Math.sin(this.time * 3.1 + index) * 0.04);
      });
    }
  }
}

