import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
page.setDefaultTimeout(30000);
page.on('pageerror', (error) => console.log('PAGE ERROR:', error.message));
await page.goto('http://localhost:3002', { waitUntil: 'load', timeout: 60000 });
await page.waitForTimeout(1000);
await page.getByRole('button', { name: 'Play', exact: true }).click();
await page.waitForTimeout(1000);
const result = await page.evaluate(() => {
  const { player, world } = window.__cubehaven;
  player.fly = true;
  player.position.set(2, 30, 10);
  player.yaw = 0;
  player.pitch = -0.55;
  player.velocity.set(0, 0, 0);
  player.updateCamera(0);
  const m = world.materials.water;
  m.map = null;
  m.color.set(0x3fa9d8);
  m.opacity = 0.9;
  m.transparent = true;
  m.depthWrite = false;
  m.needsUpdate = true;
  return { type: m.type };
});
console.log(result);
await page.waitForTimeout(800);
await page.screenshot({ path: 'screenshots/lake-water2.png', timeout: 60000 });
await browser.close();

