import { createRequire } from 'node:module';
import { readFileSync, mkdirSync } from 'node:fs';
import { join } from 'node:path';

const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();

const output = process.argv[2] || 'screenshots';
mkdirSync(output, { recursive: true });
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
page.on('pageerror', (e) => console.log('PAGE ERROR:', e.message));
await page.goto('http://localhost:3002', { waitUntil: 'load', timeout: 60000 });
await page.waitForTimeout(2200);
await page.getByRole('button', { name: 'Play', exact: true }).click();
await page.waitForTimeout(1200);

// Top-down orthographic-ish survey.
await page.evaluate(() => {
  const { world, camera } = window.__cubehaven;
  const THREE = window.__THREE__;
  // stop player updates from fighting the camera
  window.__cubehaven.player.setEnabled(false);
  camera.position.set(0, 120, 90);
  camera.lookAt(0, 10, -10);
  camera.fov = 60;
  camera.updateProjectionMatrix();
  const row = [];
  for (let z = 40; z >= -45; z -= 5) {
    const heights = [];
    for (let x = -40; x <= 40; x += 10) heights.push(world.heightAt(x, z));
    row.push(`${z}: ${heights.join(',')}`);
  }
  console.log(row.join('\n'));
});
await page.waitForTimeout(500);
await page.screenshot({ path: join(output, 'survey.png'), timeout: 60000 });
console.log('survey done');
await browser.close();

