const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();

const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
page.on('pageerror', (e) => console.log('PAGE ERROR:', e.message));
await page.goto('http://localhost:3002', { waitUntil: 'load', timeout: 60000 });
await page.waitForTimeout(2200);
await page.getByRole('button', { name: 'Play', exact: true }).click();
await page.waitForTimeout(1200);

const info = await page.evaluate(() => {
  const { world, player, camera, scene } = window.__cubehaven;
  const out = [];
  for (const [x, z] of [[8, 0], [8, 5], [8, 10], [0, 0], [-8, 0], [16, 0], [8, -10], [8, -20]]) {
    out.push(`${x},${z} h=${world.heightAt(x, z)} block13=${world.getBlock(x, 13, z)} block10=${world.getBlock(x, 10, z)}`);
  }
  const waterMeshes = [];
  for (const [key, chunk] of world.chunks) {
    if (chunk.meshes.water) {
      const g = chunk.meshes.water.geometry;
      waterMeshes.push(`${key}:${g.attributes.position.count}v vis=${chunk.meshes.water.visible} chunkVis=${chunk.group.visible}`);
    }
  }
  return out.join('\n') + '\nWATER MESHES:\n' + waterMeshes.join('\n');
});
console.log(info);
await browser.close();

