import { createRequire } from 'node:module';
import { readFileSync, mkdirSync } from 'node:fs';
import { join } from 'node:path';

const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();

const output = '/home/runner/work/PlayGround/PlayGround/screenshots';
mkdirSync(output, { recursive: true });
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
page.setDefaultTimeout(30000);
const errors = [];
page.on('pageerror', (e) => errors.push(e.message));
page.on('console', (m) => { if (m.type() === 'error') errors.push(m.text()); });

await page.goto('http://localhost:3002', { waitUntil: 'load', timeout: 60000 });
await page.waitForTimeout(2200);

// Settings from menu
await page.getByRole('button', { name: 'Settings', exact: true }).click();
await page.waitForTimeout(600);
await page.screenshot({ path: join(output, 'settings.png') });
await page.getByRole('button', { name: 'Done', exact: true }).click();
await page.waitForTimeout(400);

// Start
await page.getByRole('button', { name: 'Play', exact: true }).click();
await page.waitForTimeout(1600);

// Block interaction: break the block in front, then place one.
const before = await page.evaluate(() => {
  const { world, player } = window.__cubehaven;
  player.pitch = -0.55;
  player.updateCamera(0);
  player.updateTarget();
  return { edits: world.editCount, target: player.target };
});
await page.evaluate(() => {
  const { player } = window.__cubehaven;
  player.breakBlock();
});
await page.waitForTimeout(500);
const afterBreak = await page.evaluate(() => window.__cubehaven.world.editCount);
await page.evaluate(() => {
  const { player } = window.__cubehaven;
  player.updateTarget();
  player.placeBlock();
});
await page.waitForTimeout(500);
const afterPlace = await page.evaluate(() => window.__cubehaven.world.editCount);

// Pause menu
await page.keyboard.press('Escape');
await page.waitForTimeout(700);
await page.screenshot({ path: join(output, 'pause.png') });
const pauseState = await page.evaluate(() => ({
  pause: document.getElementById('pause').className,
  hud: document.getElementById('hud').className,
}));
await page.getByRole('button', { name: 'Resume', exact: true }).click();
await page.waitForTimeout(500);

// Fly + save
await page.keyboard.press('KeyF');
await page.waitForTimeout(300);
const flyState = await page.evaluate(() => window.__cubehaven.player.fly);

// Mobile viewport
const mobile = await browser.newPage({ viewport: { width: 390, height: 844 }, isMobile: true, hasTouch: true, deviceScaleFactor: 2 });
await mobile.goto('http://localhost:3002', { waitUntil: 'load', timeout: 60000 });
await mobile.waitForTimeout(2200);
await mobile.screenshot({ path: join(output, 'mobile-menu.png') });
await mobile.getByRole('button', { name: 'Play', exact: true }).click();
await mobile.waitForTimeout(1800);
await mobile.screenshot({ path: join(output, 'mobile-game.png') });
const mobileState = await mobile.evaluate(() => ({
  touchClass: document.body.className,
  controls: document.getElementById('mobile-controls').getAttribute('aria-hidden'),
  hud: document.getElementById('hud').className,
}));

console.log(JSON.stringify({ before, afterBreak, afterPlace, pauseState, flyState, mobileState, errors }, null, 2));
await browser.close();

