const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();

const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
page.on('pageerror', (e) => console.log('PAGE ERROR:', e.message));
await page.goto('http://localhost:3002', { waitUntil: 'load', timeout: 60000 });
await page.waitForTimeout(2200);
await page.getByRole('button', { name: 'Play', exact: true }).click();
await page.waitForTimeout(1600);

const info = await page.evaluate(() => {
  const { world, player } = window.__cubehaven;
  const results = {};
  results.enabled = player.enabled;
  results.pos = player.position.toArray();
  results.yaw = player.yaw;
  results.pitch = player.pitch;
  results.ground = world.getBlock(8, 23, 28);
  results.above = world.getBlock(8, 24, 28);
  results.surface = world.surfaceY(8, 28);
  results.target0 = player.target;
  player.pitch = -0.55;
  player.updateCamera(0);
  const dir = player.getDirection().toArray();
  results.dir = dir;
  const eye = player.getEyePosition().toArray();
  results.eye = eye;
  results.hit = world.raycast({ x: eye[0], y: eye[1], z: eye[2] }, { x: dir[0], y: dir[1], z: dir[2] }, 7.2);
  results.target1 = player.updateTarget();
  results.blockAt = world.getBlock(8, 24, 25);
  return results;
});
console.log(JSON.stringify(info, null, 2));
await browser.close();

