import { createRequire } from 'node:module';
import { readFileSync, mkdirSync } from 'node:fs';
import { join } from 'node:path';

const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();

const output = '/home/runner/work/PlayGround/PlayGround/screenshots';
mkdirSync(output, { recursive: true });
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
const context = await browser.newContext({ viewport: { width: 1440, height: 900 } });
const page = await context.newPage();
page.setDefaultTimeout(30000);
const errors = [];
page.on('pageerror', (e) => errors.push(e.message));
page.on('console', (m) => { if (m.type() === 'error') errors.push(m.text()); });

await page.goto('http://localhost:3002', { waitUntil: 'load', timeout: 60000 });
await page.waitForTimeout(2200);
await page.getByRole('button', { name: 'Play', exact: true }).click();
await page.waitForTimeout(1500);

const broken = await page.evaluate(() => {
  const { world, player } = window.__cubehaven;
  player.pitch = -1.1;
  player.updateCamera(0);
  player.updateTarget();
  const hit = player.target;
  player.breakBlock();
  return { hit, edits: world.editCount };
});
await page.waitForTimeout(400);
await page.keyboard.press('Escape');
await page.waitForTimeout(500);
await page.getByRole('button', { name: 'Return to title', exact: true }).click();
await page.waitForTimeout(800);
await page.reload({ waitUntil: 'load', timeout: 60000 });
await page.waitForTimeout(2400);

const persisted = await page.evaluate(() => {
  const { world } = window.__cubehaven;
  return { edits: world.editCount, menuBlocks: document.getElementById('menu-blocks').textContent };
});
await page.getByRole('button', { name: 'Play', exact: true }).click();
await page.waitForTimeout(1600);
await page.screenshot({ path: join(output, 'game.png') });
const afterLoad = await page.evaluate(() => {
  const { world, player } = window.__cubehaven;
  return {
    edits: world.editCount,
    coords: document.getElementById('hud-coords').textContent,
    pos: player.position.toArray(),
    blockAtBroken: broken.hit ? world.getBlock(broken.hit.x, broken.hit.y, broken.hit.z) : null,
  };
});
console.log(JSON.stringify({ broken, persisted, afterLoad, errors }, null, 2));
await browser.close();

content.text:
Fresh load renders correctly. The reload shader errors were a headless context artifact. Good.

Now the path from the cabin is gone from the foreground (removed the first segment). The scene still looks good. The cabin sits on a peninsula with water around it (I can see water to the left of the cabin). Nice.

Let me consider the final polish:
- The mountain is still a pyramid. I could try a quick experiment to make it more natural by adding a second smaller peak to the right/left and reducing the symmetry. But the current peak is centered and reads as a volcano. Let me see if adding a ridge line across the back helps. Actually, from the menu screenshot the mountain looks like a big sand-colored pyramid because the menu camera sees it from an angle. In-game it's gray with snow. It's acceptable.

- The lake's near shore is a wide sand beach with a stepped edge. Fine.

- The foreground path is now gone. Maybe add a path from the spawn toward the shore again, but not to the cabin. The current scene's foreground is empty grass. A path leading from the spawn down to the beach would add interest and guide the player. Let's add a short path from spawn (8,28) to the shore (8,13), but ensure it doesn't cut into the cabin platform (it's far away). `this.buildPath(SPAWN.x, SPAWN.z + 3, 8, 13);` → from (8,31) to (8,13). This path would descend the bluff and end at the beach. It would be visible in the foreground center, leading the eye to the lake. That's a nice composition improvement.

But the path is built inside addCabin; if I add it, it's fine. The path from (8,31) to (8,13) crosses the spawn area (height 23..14). buildPath sets gravel at the top and clears 5 blocks above. At the spawn, the path would be right under the player, and the spawn point is at (8,28), so the player would spawn on the path (gravel). That's okay—a trailhead. The path ends at the shore, inviting the player to the water.

Let's add `this.buildPath(SPAWN.x, SPAWN.z + 3, SPAWN.x, 13);` before the other path calls. But note buildPath's steps and 3-wide cross may create a 3-wide path. Fine.

Also, maybe route it slightly diagonally to the cabin path: from spawn (8,31) → (8,13) then along the shore to (30,10) etc. But the cabin path currently starts at (30,10) and goes around the east side; it doesn't connect to the beach path. We can add `this.buildPath(8, 13, 20, 11)` then `(20,11) to (30,10)` to connect along the beach. That would create a continuous path from spawn to cabin along the shore, which is nice. Let's do:
```
this.buildPath(SPAWN.x, SPAWN.z + 3, SPAWN.x, 13);
this.buildPath(8, 13, 20, 11);
this.buildPath(20, 11, 30, 10);
this.buildPath(30, 10, 26, 18);
this.buildPath(26, 18, 16, 24);
this.buildPath(16, 24, SPAWN.x, SPAWN.z + 3);
```
Hmm, the last segment (16,24) to spawn creates a second path up the bluff, making a loop. That might be nice (a loop trail), or messy. Let's simplify: a trail from spawn down to the shore, along the beach east to the cabin, and a branch up the east slope back to spawn? A loop is actually good for exploration.

