import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';

const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();

const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
const page = await browser.newPage({ viewport: { width: 390, height: 844 }, isMobile: true, hasTouch: true, deviceScaleFactor: 2 });
page.setDefaultTimeout(30000);
const errors = [];
page.on('pageerror', (e) => errors.push(e.message));
await page.goto('http://localhost:3002', { waitUntil: 'load', timeout: 60000 });
await page.waitForTimeout(4000);
await page.getByRole('button', { name: 'Play', exact: true }).click();
await page.waitForTimeout(2500);

const start = await page.evaluate(() => {
  const p = window.__cubehaven.player;
  return { pos: p.position.toArray(), yaw: p.yaw, edits: window.__cubehaven.world.editCount };
});

// Drag joystick upward with mouse (pointer events).
const box = await page.locator('#joystick').boundingBox();
await page.mouse.move(box.x + box.width / 2, box.y + box.height / 2);
await page.mouse.down();
await page.mouse.move(box.x + box.width / 2, box.y + 8, { steps: 6 });
await page.waitForTimeout(1400);
await page.mouse.up();
await page.waitForTimeout(400);
const moved = await page.evaluate(() => {
  const p = window.__cubehaven.player;
  return { pos: p.position.toArray(), touch: { ...p.touchMove } };
});

// Drag canvas to look.
const cbox = await page.locator('#scene').boundingBox();
await page.mouse.move(cbox.x + cbox.width / 2, cbox.y + cbox.height / 2);
await page.mouse.down();
await page.mouse.move(cbox.x + cbox.width / 2 + 120, cbox.y + cbox.height / 2 + 40, { steps: 8 });
await page.mouse.up();
await page.waitForTimeout(400);
const looked = await page.evaluate(() => {
  const p = window.__cubehaven.player;
  return { yaw: p.yaw, pitch: p.pitch };
});

// Break via touch button.
await page.locator('#btn-mobile-break').dispatchEvent('pointerdown');
await page.waitForTimeout(400);
const edited = await page.evaluate(() => window.__cubehaven.world.editCount);

console.log(JSON.stringify({ start, moved, looked, edited, errors }, null, 2));
await browser.close();

import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';

const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();

const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
const page = await browser.newPage({ viewport: { width: 390, height: 844 }, isMobile: true, hasTouch: true, deviceScaleFactor: 2 });
page.setDefaultTimeout(30000);
const errors = [];
page.on('pageerror', (e) => errors.push(e.message));
await page.goto('http://localhost:3002', { waitUntil: 'load', timeout: 60000 });
await page.waitForTimeout(4000);
await page.getByRole('button', { name: 'Play', exact: true }).click();
await page.waitForTimeout(2500);

await page.evaluate(() => {
  const p = window.__cubehaven.player;
  p.pitch = -1.1;
  p.updateCamera(0);
  p.updateTarget();
});
const client = await page.context().newCDPSession(page);
const cbox = await page.locator('#scene').boundingBox();
const cx = cbox.x + cbox.width / 2;
const cy = cbox.y + cbox.height / 2;
const yaw0 = await page.evaluate(() => window.__cubehaven.player.yaw);
await client.send('Input.dispatchTouchEvent', { type: 'touchStart', touchPoints: [{ x: cx, y: cy }] });
await client.send('Input.dispatchTouchEvent', { type: 'touchMove', touchPoints: [{ x: cx + 110, y: cy + 30 }] });
await client.send('Input.dispatchTouchEvent', { type: 'touchEnd', touchPoints: [] });
await page.waitForTimeout(400);
const yaw1 = await page.evaluate(() => window.__cubehaven.player.yaw);

const breakBox = await page.locator('#btn-mobile-break').boundingBox();
await page.touchscreen.tap(breakBox.x + breakBox.width / 2, breakBox.y + breakBox.height / 2);
await page.waitForTimeout(500);
const result = await page.evaluate(() => ({
  edits: window.__cubehaven.world.editCount,
  yaw: window.__cubehaven.player.yaw,
  pitch: window.__cubehaven.player.pitch,
}));

console.log(JSON.stringify({ yaw0, yaw1, result, errors }, null, 2));
await browser.close();

